function money(value) { return `₱${Number(value || 0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`; }
function points(value) { return Number(value || 0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function dateTime(value) { if (!value) return '—'; const date=new Date(value); return Number.isNaN(date.getTime())?'—':date.toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'}); }
function membershipTimeline(user){
  const plan=workerPlans.find(item=>item.level===Number(user?.activeWorker||0));
  const started=user?.membershipStartedAt?new Date(user.membershipStartedAt):null;
  const expires=user?.membershipExpiresAt?new Date(user.membershipExpiresAt):null;
  const validStart=started&&!Number.isNaN(started.getTime()); const validEnd=expires&&!Number.isNaN(expires.getTime());
  const now=Date.now(); const active=Boolean(plan&&validEnd&&expires.getTime()>now);
  const totalDays=validStart&&validEnd?Math.max(1,Math.ceil((expires-started)/DAY_MS)):360;
  const daysLeft=active?Math.max(0,Math.ceil((expires-now)/DAY_MS)):0;
  const elapsed=active?Math.max(0,Math.min(totalDays,totalDays-daysLeft)):0;
  return {plan,started:validStart?started:null,expires:validEnd?expires:null,active,totalDays,daysLeft,elapsed,progress:active?Math.min(100,Math.max(0,(elapsed/totalDays)*100)):0};
}
function esc(value='') { return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function toast(message, error=false) { const node=$('#toast'); node.textContent=message; node.className=`toast show${error?' error':''}`; clearTimeout(toast.timer); toast.timer=setTimeout(()=>node.className='toast',3200); }
async function api(path, options={}) {
  const response = await fetch(path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`} : {}),...(options.headers||{})}});
  const type=response.headers.get('content-type')||''; const data=type.includes('json')?await response.json():await response.text();
  if (!response.ok) { if(response.status===401 && !path.startsWith('/api/auth/')){state.user=null;showAuth();} throw new Error(data.message||data||'Request failed.'); } return data;
}
function userInitials(user){return (user?.fullName||'CW').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();}
function profileImage(user,cls=''){const initials=userInitials(user);return user?.profileImageDataUrl?`<img class="${cls}" src="${user.profileImageDataUrl}" alt="${esc(user.fullName||'Member')} profile photo">`:esc(initials);}
function setUser(user){ state.user=user; if(!user)return; $('#sideName').textContent=user.fullName; $('#sideId').textContent=`ID ${user.accountId}`; $$('.avatar').forEach(n=>{if(!n.classList.contains('large')||n.closest('.user-mini'))n.innerHTML=profileImage(user,'avatar-image')}); }
function setActiveNav(page){ $$('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav===page)); }
function referralCodeFromUrl(){const query=new URLSearchParams(window.location.search);return String(query.get('referral')||query.get('code')||query.get('')||'').trim().toUpperCase();}
function setAuthMode(mode='login',referralCode=referralCodeFromUrl()){const login=mode==='login';$('#loginForm').hidden=!login;$('#registerForm').hidden=login;$$('[data-auth]').forEach(button=>button.classList.toggle('active',button.dataset.auth===mode));const input=$('#registerForm [name=referralCode]');if(!login&&input&&referralCode)input.value=referralCode;}
function openAuth(mode='login',referralCode=referralCodeFromUrl()){ $('#authView').hidden=false; $('#appView').hidden=true; setAuthMode(mode,referralCode); $('#authModal').hidden=false; document.body.classList.add('auth-open'); }
function closeAuth(){ $('#authModal').hidden=true;document.body.classList.remove('auth-open'); }
function showRegister(referralCode=referralCodeFromUrl()){openAuth('register',referralCode);}
function showAuth(){ $('#authView').hidden=false; $('#appView').hidden=true; if(referralCodeFromUrl()) return showRegister(); closeAuth(); }
function showApp(){ closeAuth(); $('#authView').hidden=true; $('#appView').hidden=false; }
function logout(){ state.token=''; state.user=null; fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'}).catch(()=>{}); showAuth(); }
function openModal(html){ const body=$('#modalBody'); body.classList.remove('support-modal','announcement-modal'); body.innerHTML=html; $('#modal').hidden=false; }
function closeModal(){ const body=$('#modalBody'); $('#modal').hidden=true; body.classList.remove('support-modal','announcement-modal'); body.innerHTML=''; }
function modalHead(title,subtitle=''){return `<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p class="muted">${esc(subtitle)}</p>`:''}</div><button data-close-modal>&times;</button></div>`;}
function pageTitle(title,subtitle,action=''){return `<div class="page-title"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function metric(label,value,cls=''){return `<div class="metric ${cls}"><small>${label}</small><strong>${value}</strong></div>`;}
function empty(message){return `<div class="card empty">${esc(message)}</div>`;}
function announcementCard(item,compact=false){return `<article class="dashboard-announcement ${compact?'compact':''}">${item.imageDataUrl?`<img src="${item.imageDataUrl}" alt="">`:''}<div><span class="overline">ANNOUNCEMENT</span><strong>${esc(item.title)}</strong><p>${esc(item.message)}</p><small>${dateTime(item.createdAt)}</small></div></article>`;}
function popupAnnouncement(item){openModal(`<div class="announcement-popup-head"><div><span class="overline">ANNOUNCEMENT</span><h2>${esc(item.title)}</h2></div><button class="announcement-exit" data-close-modal aria-label="Close announcement" title="Close">×</button></div><article class="announcement-popup">${item.imageDataUrl?`<img src="${item.imageDataUrl}" alt="Announcement image">`:''}<p>${esc(item.message)}</p><small>${dateTime(item.createdAt)}</small></article>`);$('#modalBody').classList.add('announcement-modal');}
function referralLink(code){return `${window.location.origin}/referral?referral=${encodeURIComponent(code)}`;}
function referralQrUrl(link){return `https://api.qrserver.com/v1/create-qr-code/?size=260x260&format=svg&data=${encodeURIComponent(link)}`;}
async function copyReferralLink(link){try{await navigator.clipboard.writeText(link);toast('Referral link copied.')}catch{const area=document.createElement('textarea');area.value=link;document.body.append(area);area.select();document.execCommand('copy');area.remove();toast('Referral link copied.');}}
async function shareReferralLink(link){if(navigator.share){try{await navigator.share({title:'Join ClickWorker',text:'Join ClickWorker using my referral link.',url:link});}catch(error){if(error.name!=='AbortError')toast('Could not open share options.',true)}}else copyReferralLink(link);}
function referralShareCard(code){const link=referralLink(code);return `<section class="card referral-share-card"><div class="referral-share-copy"><span class="overline">REFERRAL PROGRAM</span><h2>Invite friends. Earn together.</h2><p>Share this link or QR code. New members arrive on registration with your referral code already applied.</p><div class="code referral-code">${esc(code)}</div><label class="field-label">Referral link</label><div class="referral-link-row"><input class="form-input" value="${esc(link)}" readonly aria-label="Referral link"><button class="secondary" type="button" data-action="copy-referral" data-link="${esc(link)}">Copy link</button></div><div class="referral-share-actions"><button class="primary" type="button" data-action="share-referral" data-link="${esc(link)}">Share invite</button></div></div><figure class="referral-qr"><img src="${referralQrUrl(link)}" alt="QR code for referral code ${esc(code)}"><figcaption>Scan to register with code <strong>${esc(code)}</strong></figcaption></figure></section>`;}

$$('[data-auth]').forEach(button=>button.onclick=()=>setAuthMode(button.dataset.auth));
$$('[data-open-auth]').forEach(button=>button.onclick=()=>openAuth(button.dataset.openAuth));
$$('[data-close-auth]').forEach(button=>button.onclick=closeAuth);
