$('#loginForm').onsubmit=async event=>{event.preventDefault();const form=Object.fromEntries(new FormData(event.currentTarget));try{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify(form)});setUser(data.user);showApp();navigate(data.user.guidanceAccepted?'dashboard':'guidance');}catch(error){toast(error.message,true)}};
$('#sendRegistrationOtp').onclick=async()=>{const form=$('#registerForm');const phone=new FormData(form).get('phone');const button=$('#sendRegistrationOtp');button.disabled=true;let sent=false;try{const data=await api('/api/auth/register/send-otp',{method:'POST',body:JSON.stringify({phone})});sent=true;toast(data.message);$('#registrationOtpWrap').hidden=false;$('#registerForm [name=otp]').required=true;$('#registrationOtpStatus').textContent='Code sent. It normally arrives within a minute.';button.textContent='Resend code'}catch(error){toast(error.message,true)}finally{if(sent)setTimeout(()=>button.disabled=false,30000);else button.disabled=false}};$('#registerForm').onsubmit=async event=>{event.preventDefault();const form=Object.fromEntries(new FormData(event.currentTarget));if(form.password!==form.confirmPassword)return toast('Passwords do not match.',true);if(!form.otp){$('#registrationOtpWrap').hidden=false;return toast('Send and enter the SMS verification code first.',true)}delete form.confirmPassword;try{const data=await api('/api/auth/register',{method:'POST',body:JSON.stringify(form)});setUser(data.user);showApp();navigate('guidance')}catch(error){toast(error.message,true)}};
$('#logoutButton').onclick=logout; $('[data-close-modal]').onclick=closeModal; $('#modal').addEventListener('click',e=>{if(e.target.matches('[data-close-modal]'))closeModal()});
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav)navigate(nav.dataset.nav);const close=e.target.closest('[data-close-modal]');if(close)closeModal();const action=e.target.closest('[data-action]');if(!action)return;if(action.dataset.action==='navigate')navigate(action.dataset.page);else if(action.dataset.action==='support')openSupport();else if(action.dataset.action==='notifications')openNotifications();else if(action.dataset.action==='redeem')openRedeem();else if(action.dataset.action==='logout')logout();else if(action.dataset.action==='copy-referral')copyReferralLink(action.dataset.link);else if(action.dataset.action==='share-referral')shareReferralLink(action.dataset.link);});
$('#notificationButton').onclick=()=>openNotifications();

async function navigate(page){ state.page=page;setActiveNav(page);$('#page').className=`page page-${page}`;window.scrollTo(0,0);const renderers={dashboard:renderDashboard,commission:renderCommission,earn:renderEarn,weeklyGame:renderWeeklyGame,duty:renderDuty,deposit:renderDeposit,profile:renderProfile,faq:renderFaq,guidance:renderGuidance,transactions:renderTransactions,withdraw:renderWithdraw,referral:renderReferral,partnerships:renderPartnerships,membership:renderMembership,completed:renderCompleted,analytics:renderAnalytics,admin:renderAdmin,commissionControl:renderCommissionControl};try{await (renderers[page]||renderDashboard)();}catch(error){$('#page').innerHTML=pageTitle('Could not load page',error.message)+empty('Check local server connection and try again.');}}

async function refreshProfile(){const data=await api('/api/account/profile');setUser(data.user);return data;}
async function renderDashboard(){
  await refreshProfile();
  const u=state.user; let notifications=[];
  try{notifications=(await api('/api/notifications')).notifications}catch{}
  $('#notificationDot').classList.toggle('on',notifications.some(x=>!x.read));
  const plan=workerPlans.find(x=>x.level===u.activeWorker); const announcements=notifications.filter(item=>item.senderType==='admin');
  const quick=[['Transactions','transactions','transactions',''],['Share & Earn','referral','referral',''],['Guidance','guidance','guidance',''],['Rewards','rewards','earn','new'],['News','news','notifications','new'],['Task Center','tasks','duty','new']];
  $('#page').innerHTML=`
  <section class="dash-head"><div><span class="overline">MEMBER WORKSPACE</span><h1>Welcome back, ${esc(u.fullName.split(' ')[0])}</h1><p>Track tasks, earnings, and current membership.</p></div><div class="dash-head-actions"><button class="icon-btn dash-action" data-action="support" aria-label="Open customer support">${icon('support')}</button><button class="icon-btn dash-action" data-action="notifications" aria-label="Open notifications">${icon('bell')}<i class="action-dot ${notifications.some(x=>!x.read)?'show':''}"></i></button></div></section>
  <section class="dashboard-grid"><article class="wallet-panel"><span>Available cash</span><strong>${money(u.balance)}</strong><small>${Number(u.points||0).toFixed(2)} earning points</small><div><button data-action="navigate" data-page="deposit">Deposit</button><button data-action="navigate" data-page="withdraw">Withdraw</button><button data-action="navigate" data-page="transactions">History</button></div></article><article class="member-panel"><span class="status-dot"></span><small>MEMBERSHIP</small><strong>${esc(u.membershipLevel)}</strong><p>${plan?`${plan.max} tasks available each day`:'Choose a worker plan to unlock tasks'}</p><button data-action="navigate" data-page="duty">${plan?'Open tasks':'Explore plans'}</button></article></section>
  <section class="dash-content"><div><section class="video-panel"><video autoplay muted loop playsinline src="/assets/dashboard_video.mp4"></video><div><span class="overline">CLICKWORKER</span><h2>Work smarter. Earn on your terms.</h2></div></section><div class="section-head"><h2>Quick access</h2></div><div class="quick-grid minimal">${quick.map(([label,iconName,target,badge])=>`<button class="quick ${badge?'has-badge':''}" data-action="${target==='notifications'?'notifications':'navigate'}" ${target==='notifications'?'':`data-page="${esc(target)}"`}><i>${icon(iconName)}</i><span>${label}</span>${badge?'<em>NEW</em>':''}<b>›</b></button>`).join('')}</div><section class="dashboard-help-grid"><article class="dashboard-help support-help"><div class="help-icon">${icon('support')}</div><div><span class="overline">NEED HELP?</span><h2>Contact Support</h2><p>Questions about your account, wallet, or tasks? Our support team is here to help.</p><button class="help-link" data-action="support">Message support <b>→</b></button></div></article><article class="dashboard-help news-help"><div class="help-icon">${icon('news')}</div><div><span class="overline">STAY UPDATED</span><h2>News &amp; Announcements</h2><p>See system notices, new opportunities, and important account updates.</p><button class="help-link" data-action="notifications">View announcements <b>→</b></button></div><i class="help-new">NEW</i></article></section>${announcements.length?`<section class="dashboard-announcements"><div class="section-head"><h2>Announcements</h2><button data-action="notifications">All</button></div>${announcements.slice(0,3).map(item=>announcementCard(item)).join('')}</section>`:''}</div>
  <aside><div class="section-head"><h2>Today</h2></div><section class="today-panel"><div class="today-ring">${plan?plan.max:0}<small>tasks</small></div><div><strong>${plan?plan.type:'No active work'}</strong><p>${plan?`${money(plan.rate)} per completed task`:'Activate a plan to begin.'}</p></div><button data-action="navigate" data-page="duty">${plan?'Start':'View plans'}</button></section><div class="section-head"><h2>Updates</h2><button data-action="notifications">All</button></div><section class="updates-panel">${notifications.slice(0,3).map(n=>`<button data-action="notifications"><i></i><span><strong>${esc(n.title)}</strong><small>${esc(n.message)}</small></span></button>`).join('')||'<p class="muted">No updates yet.</p>'}</section></aside></section>`;
  const unseen=announcements.find(item=>!localStorage.getItem(`cw_announcement_seen_${u.id}_${item.id}`));if(unseen){localStorage.setItem(`cw_announcement_seen_${u.id}_${unseen.id}`,'1');setTimeout(()=>popupAnnouncement(unseen),250);}
}

async function renderGuidance(){const accepted=state.user?.guidanceAccepted;$('#page').innerHTML=`${pageTitle('ClickWorker Guidance','Read workplace information before continuing.')}<article class="card guidance">${guidanceSections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<div class="card" style="padding:18px;margin-top:25px"><strong>Workplace acknowledgement</strong><p>By accepting, you confirm you understand task availability and income can vary.</p><button class="primary" id="acceptGuidance">${accepted?'Back to Dashboard':'Accept and Continue'}</button></div></article>`;$('#acceptGuidance').onclick=async()=>{if(!accepted){const data=await api('/api/account/guidance/accept',{method:'POST',body:'{}'});setUser(data.user);toast(data.message)}navigate('dashboard')};}

async function renderCommission(){
  clearInterval(window.commissionCountdownTimer);
  const data=await api('/api/commission/earn'); state.commission=data;
  $('#page').innerHTML=`<header class="commission-head"><div><span class="overline">COMMISSION</span><h1>Earn portfolio</h1><p>Review available partners and current order windows.</p></div><button class="line-action" id="lockedOrders"><span>${data.orders.length}</span> Locked orders</button></header><section class="portfolio-strip"><div><small>Cash wallet</small><strong>${money(data.cashWallet)}</strong></div><div><small>Overall earnings</small><strong class="green">${money(data.overallEarnings)}</strong></div><div><small>Orders escrow</small><strong>${money(data.ordersEscrow)}</strong></div><div class="withdrawable-commission"><small>Withdrawable balance</small><strong>${money(data.withdrawableBalance)}</strong><button id="transferCommissionFunds" ${Number(data.withdrawableBalance)<=0?'disabled':''}>Transfer to Cash Wallet</button></div></section><div class="commission-toolbar"><div class="tabs" id="commissionTabs"><button class="active" data-filter="all">All partners</button><button data-filter="Simple Earn">Simple earn</button><button data-filter="Stable Rewards">Stable rewards</button></div><span>${data.companies.length} opportunities</span></div><div class="company-grid compact" id="companyGrid">${companyCards(data.companies)}</div>`;
  $('#commissionTabs').onclick=e=>{const button=e.target.closest('button');if(!button)return;$$('button',$('#commissionTabs')).forEach(x=>x.classList.toggle('active',x===button));const list=button.dataset.filter==='all'?data.companies:data.companies.filter(x=>x.category===button.dataset.filter);$('#companyGrid').innerHTML=companyCards(list)};
  $('#companyGrid').onclick=e=>{const card=e.target.closest('[data-company]');if(card)openCompany(data.companies.find(x=>x.id===card.dataset.company),data)};
  $('#lockedOrders').onclick=()=>openOrders(data.orders);
  $('#transferCommissionFunds').onclick=async()=>{try{const result=await api('/api/commission/earn/transfer-unlocked',{method:'POST',body:'{}'});setUser(result.user);toast(result.message);renderCommission()}catch(error){toast(error.message,true)}};
  window.commissionCountdownTimer=setInterval(refreshDeadlineTimers,1000);
}

function companyLogo(id){const names={'questionpro':'company_questionpro.webp','satismeter':'company_satismeter.webp','intellipulse':'company_intellipulse.jpg','spoking-polls':'company_spoking_polls.png','mapps-forsurvey':'company_mapps_forsurvey.png','userloop':'company_userloop.webp','multirater':'company_multirater.webp','truesample':'company_truesample.webp','enquirelabs':'company_enquirelabs.webp','number-analytics':'company_number_analytics.webp'};return names[id]?`/assets/${names[id]}`:'';}
function deadlineText(value){const remaining=new Date(value).getTime()-Date.now();if(!Number.isFinite(remaining)||remaining<=0)return 'Expired';const days=Math.floor(remaining/86400000),hours=Math.floor((remaining%86400000)/3600000),minutes=Math.floor((remaining%3600000)/60000),seconds=Math.floor((remaining%60000)/1000);return `${days}d ${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;}
function refreshDeadlineTimers(){ $$('[data-deadline]').forEach(node=>node.textContent=deadlineText(node.dataset.deadline)); }
function companyCards(list){setTimeout(refreshDeadlineTimers,0);return list.map(c=>`<article class="company-row" data-company="${c.id}"><div class="company-logo-wrap"><img class="company-logo" src="${companyLogo(c.id)}" alt="${esc(c.name)}"></div><div class="company-name"><strong>${esc(c.name)}</strong><small>${esc(c.category)} · ${c.lockDays} days · <b class="stock-deadline countdown" data-deadline="${c.deadlineAt}">${deadlineText(c.deadlineAt)}</b></small></div><div class="company-rate"><small>Daily return</small><strong>${c.dailyReturnRate}%</strong></div><div class="company-range"><small>Investment range</small><strong>${money(c.min)} – ${money(c.max)}</strong></div><button aria-label="View ${esc(c.name)}">›</button></article>`).join('')||empty('No company orders are deployed right now. Check back when a new stock window opens.');}

function openCompany(c,data){
  const calculate = amount => Number.isFinite(amount) && amount > 0 ? amount * (Number(c.dailyReturnRate) / 100) : 0;
  const totalEarnings = amount => calculate(amount) * Number(c.lockDays || 0);
  openModal(`${modalHead(c.name,c.location)}<img class="company-logo" src="${companyLogo(c.id)}"><p>${esc(c.description)}</p><div class="metrics">${metric('Daily Return Rate',`${c.dailyReturnRate}%`)}${metric('Lock Period',`${c.lockDays} days`)}${metric('Minimum',money(c.min))}${metric('Maximum',money(c.max))}</div><div class="stock-window">Order window closes <b data-deadline="${c.deadlineAt}">${deadlineText(c.deadlineAt)}</b> · Limit: <b>${c.perUserLimit} order${c.perUserLimit===1?'':'s'} per member</b></div><form id="orderForm" class="form-grid"><label class="field-label">Order amount</label><input class="form-input" name="amount" type="number" min="${c.min}" max="${c.max}" step=".01" placeholder="${c.min}" required><section class="earnings-preview"><span>Estimated earnings per day</span><strong id="dailyEarnings">${money(0)}</strong><small>Order amount × ${c.dailyReturnRate}% daily return rate</small></section><section class="earnings-preview total"><span>Estimated total earnings for ${c.lockDays} days</span><strong id="totalEarnings">${money(0)}</strong><small>Estimated daily earnings × ${c.lockDays} locked days. This is an estimate, not a guarantee.</small></section><div class="order-range"><span>Minimum ${money(c.min)}</span><span>Maximum ${money(c.max)}</span></div><small class="muted">Cash Wallet: ${money(data.cashWallet)}</small><button class="primary">Place Order</button></form>`);
  const input=$('#orderForm input[name=amount]');
  const update=()=>{const amount=Number(input.value);$('#dailyEarnings').textContent=money(calculate(amount));$('#totalEarnings').textContent=money(totalEarnings(amount));};
  input.addEventListener('input',update); update();
  $('#orderForm').onsubmit=async e=>{e.preventDefault();try{const amount=Number(new FormData(e.currentTarget).get('amount'));const result=await api('/api/commission/earn/subscribe',{method:'POST',body:JSON.stringify({companyId:c.id,amount})});setUser(result.user);toast(result.message);closeModal();renderCommission()}catch(error){toast(error.message,true)}};
}
function openOrders(orders){openModal(`${modalHead('Locked Orders','Current company positions')}${orders.length?`<div class="list">${orders.map(o=>`<div class="list-row"><div class="grow"><strong>${esc(o.companyName)}</strong><small>${o.status==='Locked'?`${money(o.amount)} locked · ${o.remainingDays} days remaining`:`${money(o.withdrawableAmount||0)} available to transfer`}</small></div><div><b>${money(o.accruedRevenue)}</b><br><span class="pill ${o.status.toLowerCase()}">${o.status}</span></div></div>`).join('')}</div>`:empty('No locked orders.')}`);}

