function openProfileEditor(user){
  openModal(`${modalHead('Edit Profile','Customize your photo, name, and username.')}<form id="profileEditForm" class="form-grid"><label class="field-label">Profile photo or face photo</label><div class="photo-upload-row">${profileImage(user,'profile-editor-image')}<input class="form-input" id="profilePhotoInput" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Choose profile photo"></div><button type="button" class="secondary" id="openFaceCamera">Use camera for face photo</button><div id="faceCameraPanel" hidden><video id="faceCameraPreview" class="face-camera-preview" autoplay playsinline muted></video><canvas id="faceCameraCanvas" hidden></canvas><div class="agreement-canvas-actions"><button type="button" class="secondary" id="captureFacePhoto">Capture photo</button><button type="button" class="secondary" id="closeFaceCamera">Close camera</button></div></div><small class="muted">PNG, JPG, or WebP. Maximum 3 MB. Face photos are used as your profile picture; this does not perform biometric identity verification.</small><label class="field-label">Full name</label><input class="form-input" name="fullName" value="${esc(user.fullName)}" minlength="3" maxlength="80" required><label class="field-label">Username</label><input class="form-input" name="username" value="${esc(user.username||'')}" minlength="3" maxlength="24" placeholder="your.username"><small class="muted">Letters, numbers, dots, and underscores only.</small><button class="primary">Save Profile</button></form>`);
  let cameraStream=null; let capturedImageDataUrl=''; const stopCamera=()=>{cameraStream?.getTracks().forEach(track=>track.stop());cameraStream=null;const panel=$('#faceCameraPanel');if(panel)panel.hidden=true;};
  $('#openFaceCamera').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access is not supported in this browser.');cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});const video=$('#faceCameraPreview');video.srcObject=cameraStream;$('#faceCameraPanel').hidden=false}catch(error){toast(error.message||'Could not access the camera.',true)}};
  $('#closeFaceCamera').onclick=stopCamera;
  $('#captureFacePhoto').onclick=()=>{const video=$('#faceCameraPreview');if(!video.videoWidth)return toast('Camera is still starting. Try again.',true);const canvas=$('#faceCameraCanvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);capturedImageDataUrl=canvas.toDataURL('image/jpeg',.9);stopCamera();toast('Face photo captured. Save Profile to apply it.');};
  $('#profileEditForm').onsubmit=async e=>{e.preventDefault();try{const form=e.currentTarget;const photo=$('#profilePhotoInput').files[0];let imageDataUrl=capturedImageDataUrl;if(photo){if(!['image/png','image/jpeg','image/webp'].includes(photo.type)||photo.size>3000000)throw new Error('Choose a PNG, JPG, or WebP image smaller than 3 MB.');imageDataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Unable to read the selected image.'));reader.readAsDataURL(photo);});}if(imageDataUrl){const uploaded=await api('/api/account/profile-picture',{method:'POST',body:JSON.stringify({imageDataUrl})});setUser(uploaded.user);}const data=await api('/api/account/profile',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(form)))});setUser(data.user);toast('Profile updated.');stopCamera();closeModal();renderProfile()}catch(error){toast(error.message,true)}};
}
