async function renderWithdraw(){
  const data=await api('/api/wallet/withdrawal-status'); const w=data.withdrawal; const balance=Number(w.balance??state.user?.balance??0); const suggestions=[150,600,1500,4000,10000,30000,100000,250000,700000,2000000]; const scheduleTitle=w.schedule?`${w.schedule.group} · ${w.schedule.label}`:'No active membership'; const nextText=w.nextPeriodAt?`${new Date(w.nextPeriodAt).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'})} · ${w.daysUntilNextPeriod} day${w.daysUntilNextPeriod===1?'':'s'} left`:'—'; const canChoose=Boolean(w.canWithdraw&&data.bankAccount&&data.hasWithdrawalPassword); const stateCopy=w.alreadyRequested?`You already submitted ${money(w.requestedWithdrawal.amount)} for this scheduled period. Your next schedule is ${nextText}.`:w.eligible?'Choose an amount that does not exceed your Cash Wallet balance.':' '+w.reason;
  $('#page').innerHTML=`${pageTitle('Withdraw','One withdrawal request is available only during your assigned schedule.',`<button class="secondary" id="withdrawStatus">Withdrawal Status</button>`)}<div class="metrics">${metric('Cash Wallet',money(balance),'orange')}${metric('Assigned schedule',esc(w.schedule?.label||'—'))}${metric('Next withdrawal',w.daysUntilNextPeriod??'—')}${metric('Requests this period',w.alreadyRequested?'1 of 1':'0 of 1')}</div><div class="withdraw-layout"><section class="card form-card"><h2>Withdrawal account</h2>${data.bankAccount?`<div class="bank-summary"><div class="category-icon">▣</div><div><strong>${esc(data.bankAccount.bankName)}</strong><div class="muted">${esc(data.bankAccount.accountName)} · ${esc(data.bankAccount.accountNumberMasked)}</div></div></div>`:'<p class="muted">One personal bank account is mandatory before withdrawal.</p>'}<button class="secondary" id="bankButton">${data.bankAccount?'Update Bank Account':'Add Bank Account'}</button>${!data.hasWithdrawalPassword?'<button class="secondary" id="passwordButton">Set Withdrawal Password</button>':''}<section class="withdraw-window ${w.eligible&&!w.alreadyRequested?'open':''}"><strong>${w.eligible&&!w.alreadyRequested?'Withdrawal window open':w.alreadyRequested?'Withdrawal already submitted':'Next withdrawal period'}</strong><span>${esc(scheduleTitle)}</span><small>${esc(stateCopy)}</small></section><form id="withdrawForm" class="form-grid"><label class="field-label">Select withdrawal amount</label><div class="withdraw-suggestions only"><small>Available Cash Wallet: ${money(balance)}</small><div>${suggestions.map(amount=>{const enabled=canChoose&&amount<=balance;return `<button type="button" class="withdraw-suggestion" data-withdraw-amount="${amount}" ${enabled?'':'disabled'}>${money(amount)}</button>`;}).join('')}</div></div><input type="hidden" name="amount" required><label class="field-label">6-digit withdrawal password</label><input class="form-input" name="withdrawalPassword" type="password" inputmode="numeric" maxlength="6" ${canChoose?'':'disabled'} required><button class="primary" id="submitWithdrawal" disabled>${w.alreadyRequested?'Withdrawal already submitted':w.eligible?'Select an amount':'Unavailable until your schedule'}</button></form></section><aside class="withdraw-note"><span class="withdraw-note-icon">◷</span><div><span class="overline">WITHDRAWAL GUIDE</span><h2>Scheduled withdrawals</h2><p class="withdraw-lead">No weekly monetary limit. Each member can request one suggested amount up to their available Cash Wallet balance per schedule.</p><section><h3>Worker schedule</h3><div class="withdraw-schedule"><span>Worker 1–3</span><b>Monday</b><span>Worker 4–6</span><b>Wednesday</b><span>Worker 7–9</span><b>Friday</b></div></section><section><h3>Withdrawal hours</h3><ul><li>Requests are open only from <b>8:00 AM to 6:00 PM Manila time.</b></li><li>One request is allowed for each assigned schedule period.</li><li>Only enabled suggested amounts can be chosen.</li><li>Rejected requests return funds to Cash Wallet, but do not create another request slot for that schedule.</li></ul></section></div></aside></div>`;
  $('#bankButton').onclick=()=>openBankForm(data.bankAccount);if($('#passwordButton'))$('#passwordButton').onclick=openPasswordForm;$('#withdrawStatus').onclick=openWithdrawalStatus;$$('[data-withdraw-amount]').forEach(button=>button.onclick=()=>{const amount=Number(button.dataset.withdrawAmount);$('#withdrawForm [name=amount]').value=amount;$$('[data-withdraw-amount]').forEach(item=>item.classList.toggle('selected',item===button));const submit=$('#submitWithdrawal');submit.disabled=false;submit.textContent=`Submit ${money(amount)} Withdrawal`;});$('#withdrawForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));f.amount=Number(f.amount);if(!suggestions.includes(f.amount)||f.amount>balance)return toast('Choose an enabled suggested withdrawal amount.',true);try{const result=await api('/api/wallet/withdraw',{method:'POST',body:JSON.stringify(f)});setUser(result.user);toast(result.message);renderWithdraw()}catch(error){toast(error.message,true)}};
}function openBankForm(existing){openModal(`${modalHead('Add Bank Account','Only one personal account can be linked.')}<form id="bankForm" class="form-grid"><label class="field-label">Account name</label><input class="form-input" name="accountName" value="${esc(existing?.accountName||'')}" required><label class="field-label">Bank name</label><select class="form-select" name="bankName" required><option value="">Select bank</option>${bankNames.map(x=>`<option ${x===existing?.bankName?'selected':''}>${esc(x)}</option>`).join('')}</select><label class="field-label">Account number</label><input class="form-input" name="accountNumber" inputmode="numeric" minlength="6" maxlength="20" required><button class="primary">Save Bank Account</button></form>`);$('#bankForm').onsubmit=async e=>{e.preventDefault();try{const data=await api('/api/wallet/bank-account',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast(data.message);closeModal();renderWithdraw()}catch(error){toast(error.message,true)}};}
