async function openSupport(){
  try{
    const data=await api('/api/support/messages');
    openModal(`${modalHead('Support Chat','Message customer support')}<div id="chatMessages" class="chat" role="log" aria-live="polite">${data.messages.map(m=>`<div class="bubble ${m.senderType}"><strong>${m.senderType==='member'?'You':'Support'}</strong><br>${esc(m.message)}<small>${dateTime(m.createdAt)}</small></div>`).join('')||'<div class="empty">Start a conversation.</div>'}</div><form id="supportForm" class="chat-compose"><input class="form-input" name="message" placeholder="Write a message" required><button class="primary">Send</button></form>`);
    const body=$('#modalBody');
    body.classList.add('support-modal');
    const chat=$('#chatMessages');
    chat.scrollTop=chat.scrollHeight;
    $('#supportForm').onsubmit=async e=>{
      e.preventDefault();
      const form=e.currentTarget;
      const submit=form.querySelector('button');
      try{
        submit.disabled=true;
        await api('/api/support/messages',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});
        await openSupport();
      }catch(error){
        toast(error.message,true);
        submit.disabled=false;
      }
    };
  }catch(error){toast(error.message,true)}
}

